const { test } = require("node:test");
const assert = require("node:assert");
const { addMonths } = require("./dates.js");

test("adds one month within the year", () => {
  assert.strictEqual(addMonths(new Date(2026, 0, 15), 1).toDateString(), new Date(2026, 1, 15).toDateString());
});

test("Jan 31 + 1 month lands on Feb 28 (non-leap)", () => {
  assert.strictEqual(addMonths(new Date(2026, 0, 31), 1).toDateString(), new Date(2026, 1, 28).toDateString());
});

test("Jan 31 + 1 month lands on Feb 29 (leap year)", () => {
  assert.strictEqual(addMonths(new Date(2028, 0, 31), 1).toDateString(), new Date(2028, 1, 29).toDateString());
});

test("Mar 31 - 1 month lands on Feb 28", () => {
  assert.strictEqual(addMonths(new Date(2026, 2, 31), -1).toDateString(), new Date(2026, 1, 28).toDateString());
});

test("Aug 31 + 1 month lands on Sep 30", () => {
  assert.strictEqual(addMonths(new Date(2026, 7, 31), 1).toDateString(), new Date(2026, 8, 30).toDateString());
});

test("crosses year boundary with month-end clamp", () => {
  assert.strictEqual(addMonths(new Date(2026, 10, 30), 3).toDateString(), new Date(2027, 1, 28).toDateString());
});

test("preserves time of day", () => {
  const d = addMonths(new Date(2026, 0, 31, 13, 45, 7), 1);
  assert.strictEqual(d.getHours(), 13);
  assert.strictEqual(d.getMinutes(), 45);
  assert.strictEqual(d.getSeconds(), 7);
});

test("does not mutate the input date", () => {
  const input = new Date(2026, 0, 31);
  const before = input.getTime();
  addMonths(input, 1);
  assert.strictEqual(input.getTime(), before);
});

